      "assessment": {
        "nobel_worthiness": "Fetal cell-free DNA in maternal blood enabled a major shift toward safer, high-performance prenatal screening.",
        "attribution": "Lo is a clear central figure in identifying and establishing the diagnostic potential of circulating fetal DNA.",
        "maturity": "The method has been extensively validated and implemented internationally over many years.",
        "uncertainties": [
          "Screening performance, clinical governance, and equity differ across conditions and health-care settings."
        ]
      }
    },
